package com.bank.portal.config;
import com.bank.portal.domain.*; import com.bank.portal.repository.*; import java.math.BigDecimal; import java.time.LocalDate; import lombok.RequiredArgsConstructor; import org.springframework.boot.CommandLineRunner; import org.springframework.context.annotation.*; import org.springframework.security.crypto.password.PasswordEncoder;
@Configuration @RequiredArgsConstructor public class SampleData {private final PasswordEncoder encoder; @Bean CommandLineRunner seed(StaffUserRepository staff,CustomerRepository customers,CustomerUserRepository users,CardRepository cards,MerchantRepository merchants){return args->{if(staff.count()>0)return; StaffUser s=new StaffUser();s.setUsername("staff");s.setPassword(encoder.encode("Staff@123"));s.setFullName("Aarav Sharma");staff.save(s);Customer c=new Customer();c.setName("Priya Mehta");c.setEmail("priya@example.com");c.setMobileNumber("9876543210");c.setPanNumber("ABCDE1234F");customers.save(c);CustomerUser u=new CustomerUser();u.setUsername("customer");u.setPassword(encoder.encode("Customer@123"));u.setAvatarKey("mosaic-fox");u.setCustomer(c);users.save(u);CreditCard card=new CreditCard();card.setCustomer(c);card.setCardNumber("4111-2222-3333-4444");card.setCardType(CardType.GOLD);card.setCreditLimit(new BigDecimal("100000.00"));card.setAvailableCredit(new BigDecimal("100000.00"));card.setOutstandingAmount(BigDecimal.ZERO);card.setExpiryDate(LocalDate.now().plusYears(3));card.setStatus(CardStatus.ACTIVE);cards.save(card);Merchant m=new Merchant();m.setName("FreshMart");m.setCategory("Groceries");m.setLocation("Mumbai");merchants.save(m);};}}
